     \"width\": 375,\n      \"height\": 500,\n      \"title\": \"Pinus sylvestris — iNaturalist reference photograph\",\n      \"kind\": \"Reference photograph / micrograph\",\n      \"artist\": \"(c) Полина Полежанкина, some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/759222522\",\n      \"source\": \"https://www.inaturalist.org/photos/759222522\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"polytrichum-commune\": {\n      \"src\": \"/biology/reference/polytrichum-commune.jpg\",\n      \"width\": 376,\n      \"height\": 500,\n      \"title\": \"Polytrichum commune — iNaturalist reference photograph\",\n      \"kind\": \"Reference photograph / micrograph\",\n      \"artist\": \"(c) Moe Meikle, some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/758181495\",\n      \"source\": \"https://www.inaturalist.org/photos/758181495\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"dryopteris-filix-mas\": {\n      \"src\": \"/biology/reference/dryopteris-filix-mas.jpg\",\n      \"width\": 375,\n      \"height\": 500,\n      \"title\": \"Dryopteris filix-mas — iNaturalist reference photograph\",\n      \"kind\": \"Reference photograph / micrograph\",\n      \"artist\": \"(c) Полина Полежанкина, some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/759174850\",\n      \"source\": \"https://www.inaturalist.org/photos/759174850\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"saccharomyces-cerevisiae\": {\n      \"src\": \"/biology/reference/saccharomyces-cerevisiae.jpg\",\n      \"width\": 466,\n      \"height\": 500,\n      \"title\": \"Saccharomyces cerevisiae — iNaturalist reference photograph\",\n      \"kind\": \"Yeast-cell micrograph\",\n      \"artist\": \"no rights reserved\",\n      \"license\": \"CC0\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/535765009\",\n      \"source\": \"https://www.inaturalist.org/photos/535765009\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"agaricus-bisporus\": {\n      \"src\": \"/biology/reference/agaricus-bisporus.jpg\",\n      \"width\": 500,\n      \"height\": 375,\n      \"title\": \"Agaricus bisporus — iNaturalist reference photograph\",\n      \"kind\": \"Reference photograph / micrograph\",\n      \"artist\": \"(c) Lucian Clanet, some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/746061514\",\n      \"source\": \"https://www.inaturalist.org/photos/746061514\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"rhizopus-stolonifer\": {\n      \"src\": \"/biology/reference/rhizopus-stolonifer.jpg\",\n      \"width\": 500,\n      \"height\": 500,\n      \"title\": \"Rhizopus stolonifer — iNaturalist reference photograph\",\n      \"kind\": \"Reference photograph / micrograph\",\n      \"artist\": \"(c) S.R., some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/605867790\",\n      \"source\": \"https://www.inaturalist.org/photos/605867790\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"aspergillus-niger\": {\n      \"src\": \"/biology/reference/aspergillus-niger.jpg\",\n      \"width\": 375,\n      \"height\": 500,\n      \"title\": \"Aspergillus niger — iNaturalist reference photograph\",\n      \"kind\": \"Photograph of fungal growth on a substrate\",\n      \"artist\": \"(c) Thomas Mesaglio, some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/652787708\",\n      \"source\": \"https://www.inaturalist.org/photos/652787708\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"penicillium-chrysogenum\": {\n      \"src\": \"/biology/reference/penicillium-chrysogenum.jpeg\",\n      \"width\": 375,\n      \"height\": 500,\n      \"title\": \"Penicillium chrysogenum — iNaturalist reference photograph\",\n      \"kind\": \"Photograph of mould growth; species identity follows the source\",\n      \"artist\": \"(c) Bohan Jia, some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/459982091\",\n      \"source\": \"https://www.inaturalist.org/photos/459982091\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"ustilago-maydis\": {\n      \"src\": \"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Ustilago_maydis_1.jpg/960px-Ustilago_maydis_1.jpg\",\n      \"width\": 960,\n      \"height\": 1280,\n      \"title\": \"Ustilago maydis 1.jpg\",\n      \"