  \"title\": \"Euglena.gracilis.jpg\",\n      \"kind\": \"Light micrograph\",\n      \"artist\": \"Ellis O’Neill\",\n      \"license\": \"CC BY-SA 3.0\",\n      \"licenseUrl\": \"https://creativecommons.org/licenses/by-sa/3.0/\",\n      \"source\": \"https://commons.wikimedia.org/wiki/File:Euglena.gracilis.jpg\",\n      \"description\": \"Light micrograph. See the original file page for the specimen, preparation and attribution.\"\n    },\n    \"plasmodium-falciparum\": {\n      \"src\": \"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Plasmodium_falciparum_in_Red_Blood_Cells.jpg/960px-Plasmodium_falciparum_in_Red_Blood_Cells.jpg\",\n      \"width\": 960,\n      \"height\": 669,\n      \"title\": \"Plasmodium falciparum in Red Blood Cells.jpg\",\n      \"kind\": \"Light micrograph: ring stages inside red blood cells\",\n      \"artist\": \"Ernst Hempelmann\",\n      \"license\": \"Public domain\",\n      \"licenseUrl\": \"https://commons.wikimedia.org/wiki/File:Plasmodium_falciparum_in_Red_Blood_Cells.jpg\",\n      \"source\": \"https://commons.wikimedia.org/wiki/File:Plasmodium_falciparum_in_Red_Blood_Cells.jpg\",\n      \"description\": \"Light micrograph: ring stages inside red blood cells. See the original file page for the specimen, preparation and attribution.\"\n    },\n    \"trypanosoma-brucei\": {\n      \"src\": \"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Trypanosoma-brucei.jpg/960px-Trypanosoma-brucei.jpg\",\n      \"width\": 960,\n      \"height\": 822,\n      \"title\": \"Trypanosoma-brucei.jpg\",\n      \"kind\": \"Micrograph\",\n      \"artist\": \"Alan R Walker\",\n      \"license\": \"CC BY-SA 3.0\",\n      \"licenseUrl\": \"https://creativecommons.org/licenses/by-sa/3.0/\",\n      \"source\": \"https://commons.wikimedia.org/wiki/File:Trypanosoma-brucei.jpg\",\n      \"description\": \"Micrograph. See the original file page for the specimen, preparation and attribution.\"\n    },\n    \"chlamydomonas-reinhardtii\": {\n      \"src\": \"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Chlamydomonas2-1.jpg/960px-Chlamydomonas2-1.jpg\",\n      \"width\": 960,\n      \"height\": 983,\n      \"title\": \"Chlamydomonas2-1.jpg\",\n      \"kind\": \"Scanning electron micrograph\",\n      \"artist\": \"Dartmouth Electron Microscope Facility, Dartmouth College\",\n      \"license\": \"Public domain\",\n      \"licenseUrl\": \"https://commons.wikimedia.org/wiki/File:Chlamydomonas2-1.jpg\",\n      \"source\": \"https://commons.wikimedia.org/wiki/File:Chlamydomonas2-1.jpg\",\n      \"description\": \"Scanning electron micrograph. See the original file page for the specimen, preparation and attribution.\"\n    },\n    \"volvox-carteri\": {\n      \"src\": \"/biology/reference/volvox-carteri.png\",\n      \"width\": 272,\n      \"height\": 298,\n      \"title\": \"Volvox carteri — iNaturalist reference photograph\",\n      \"kind\": \"Colonial-alga micrograph\",\n      \"artist\": \"(c) http://www.unbf.ca/vip/index.htm, some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/146945432\",\n      \"source\": \"https://www.inaturalist.org/photos/146945432\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"escherichia-coli\": {\n      \"src\": \"/biology/reference/escherichia-coli.jpeg\",\n      \"width\": 375,\n      \"height\": 500,\n      \"title\": \"Escherichia coli — iNaturalist reference photograph\",\n      \"kind\": \"Culture on an agar plate; individual bacteria are not resolved\",\n      \"artist\": \"(c) Carlos Martínez, some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/471571250\",\n      \"source\": \"https://www.inaturalist.org/photos/471571250\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"bacillus-subtilis\": {\n      \"src\": \"/biology/reference/bacillus-subtilis.jpg\",\n      \"width\": 500,\n      \"height\": 375,\n      \"title\": \"Bacillus subtilis — iNaturalist reference photograph\",\n      \"kind\": \"Stained bacterial micrograph\",\n      \"artist\": \"(c) Y tambe (original uploader), some rights reserved (CC BY-SA)\",\n      \"license\": \"CC-BY-SA\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/304497\",\n      \"source\": \"https://www.inaturalist.org/photos/304497\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"vibrio-cholerae\": {\n      \"src\": \"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Vibrio_cholerae_01.jpg/960px-Vibrio_cholerae_01.jpg\",\n      \"width\": 960,\n      \"height\": 646,\n      \"title\": \"Vibrio cholerae 01.jpg\",\n      \"kind\": \"Stained, digitally colourised micrograph\",\n      \"artist\": \"CDC / Dr. Edwin P. Ewing, Jr.\",\n      \"license\": \"Public domain\",\n      \"licenseUrl\": \"https://commons.wikimedia.org/wiki/File:Vibrio_cholerae_01.jpg\",\n      \"source\": \"https://commons.wikimedia.org/wiki/File:Vibrio_cholerae_01.jpg\",\n      \"description\": \"Stained, digitally colourised micrograph. See the original file page for the specimen, preparation and attribution.\"\n    },\n    \"staphylococcus-aureus\": {\n      \"src\": \"/biology/reference/staphylococcus-aureus.jpeg\",\n      \"width\": 500,\n      \"height\": 375,\n      \"title\": \"Staphylococcus aureus — iNaturalist reference photograph\",\n      \"kind\": \"Culture on an agar plate; individual bacteria are not resolved\",\n      \"artist\": \"(c) Carlos Martínez, some rights reserved (CC BY)\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/471570884\",\n      \"source\": \"https://www.inaturalist.org/photos/471570884\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"rhizobium-leguminosarum\": {\n      \"src\": \"/biology/reference/rhizobium-leguminosarum.jpg\",\n      \"width\": 500,\n      \"height\": 375,\n      \"title\": \"Rhizobium leguminosarum — iNaturalist reference photograph\",\n      \"kind\": \"Root-nodule reference; the bacteria themselves are not visible\",\n      \"artist\": \"(c) Garth Harwood, some rights reserved (CC BY), uploaded by Garth Harwood\",\n      \"license\": \"CC-BY\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/55058276\",\n      \"source\": \"https://www.inaturalist.org/photos/55058276\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    },\n    \"halobacterium-salinarum\": {\n      \"src\": \"/biology/reference/halobacterium-salinarum.jpg\",\n      \"width\": 312,\n      \"height\": 500,\n      \"title\": \"Halobacterium salinarum — iNaturalist reference photograph\",\n      \"kind\": \"Reference photograph / micrograph\",\n      \"artist\": \"no rights reserved\",\n      \"license\": \"CC0\",\n      \"licenseUrl\": \"https://www.inaturalist.org/photos/530157263\",\n      \"source\": \"https://www.inaturalist.org/photos/530157263\",\n      \"description\": \"Species reference selected from iNaturalist taxon or research-grade observation media. Identification follows the source; appearance varies with age, sex and preparation.\"\n    }\n  }\n}\n"}, "src/lib/biology/lessons.ts": {"encoding": "utf8", "content": "export type LessonId='cells'|'mitosis'|'meiosis'|'transpiration'|'classification'|'life-processes';\nexport type Step={name:string;detail:string};\nexport type Question={prompt:string;choices:string[];answer:number;why:string};\nexport type Lesson={title:string;intro:string;principle:string;steps:Step[];questions:Question[];investigation:string[];teacher:string;misconception:string;source:string;limit:string};\nconst q=(prompt:string,choices:string[],answer:number,why:string):Question=>({prompt,choices,answer,why});\nexport const lessons:Record<LessonId,Lesson>={\n cells:{title:'Cells and organelles',intro:'Compare detailed reference illustrations with real plant and animal cell micrographs. Use the organelle guide to connect structure with function.',principle:'Cells are the basic units of living organisms; structures support different functions.',steps:[\n {name:'Cell membrane',detail:'A selectively permeable boundary controls exchange with the surroundings. Plant cells have a membrane inside the cell wall.'},\n {name:'Cytoplasm',detail:'The cytosol is fluid inside the cell; many metabolic reactions occur here. Cytoplasm includes the cytosol and organelles outside the nucleus.'},\n {name:'Nucleus',detail:'Contains most of the cell’s DNA. Gene expression helps regulate cell activities. Not every specialised animal cell retains a nucleus.'},\n {name:'Mitochondrion',detail:'Supports aerobic respiration and ATP production. Plant cells have mitochondria as well as chloroplasts.'},\n {name:'Ribosomes',detail:'Build proteins using instructions carried by messenger RNA. They occur free in the cytoplasm and on rough endoplasmic reticulum.'},\n {name:'Cell wall',detail:'The cellulose-rich plant cell wall supports and protects the cell. Animal cells do not have a cell wall.'},\n {name:'Chloroplast',detail:'In photosynthetic plant tissues, chloroplasts capture light energy for photosynthesis. Many root cells lack chloroplasts.'},\n {name:'Central vacuole',detail:'A large compartment in many mature plant cells stores water and solutes. Turgor pressure contributes to support.'}],\n questions:[q('Which structure makes proteins?',['Nucleus','Ribosomes','Cell wall'],1,'Ribosomes assemble proteins; the nucleus contains genetic instructions.'),q('Which comparison is correct?',['Plants have no mitochondria','All plant cells have chloroplasts','Plant and animal cells have membranes'],2,'Both have membranes. Photosynthetic plant cells also contain chloroplasts.'),q('Which helps support a typical mature plant cell?',['Cell wall and turgor','Only a nucleus','Only ribosomes'],0,'The wall resists the pressure generated by water inside the cell.')],\n investigation:['Compare both cell types and record four shared structures.','Select the membrane and explain why a wall cannot replace it.','Explain why a root cell may lack chloroplasts but still require mitochondria.'],teacher:'Ask pairs to act as an organelle and a cell: one names a task, the other selects the structure. Compare leaf and root cells before generalising about plants.',misconception:'Plant cells respire too. Not every plant cell contains chloroplasts. The illustration omits ER, Golgi and other structures.',source:'4-3-eukaryotic-cells',limit:'Selected organelles only. Illustration colours and proportions are schematic; microscope images show specific preparations. Wikimedia-hosted cell images need an internet connection.'},\n mitosis:{title:'Mitosis and the cell cycle',intro:'Step through DNA replication, chromosome alignment, separation and the production of two daughter cells.',principle:'One DNA replication precedes one nuclear division; chromosome set number is maintained.',steps:[\n {name:'G1 · before replication',detail:'Our simplified diploid cell has 2n = 4: two homologous pairs. Each chromosome contains one DNA molecule.'},\n {name:'S/G2 · DNA copied',detail:'DNA replicates during S phase. There are still 4 chromosomes, now with 8 sister chromatids; counting is by centromeres, not DNA strands.'},\n {name:'Prophase / prometaphase',detail:'Chromosomes condense, the spindle forms and the nuclear envelope breaks down. Each sister chromatid attaches toward an opposite pole.'},\n {name:'Metaphase',detail:'Replicated chromosomes align individually at the equator. Homologous chromosomes do not pair as tetrads.'},\n {name:'Anaphase',detail:'Sister chromatids separate and become daughter chromosomes. Each pole receives the same chromosome complement.'},\n {name:'Telophase and cytokinesis',detail:'Nuclei reform and cytoplasm divides. Two daughter cells each have 2n = 4 in this model, usually genetically alike except for new mutations.'}],\n questions:[q('What separates during mitotic anaphase?',['Homologous pairs only','Sister chromatids','Whole nuclei'],1,'Sister chromatids separate and each becomes a chromosome.'),q('After S phase, our 2n = 4 cell contains…',['4 chromosomes, 8 chromatids','8 chromosomes, 8 chromatids','2 chromosomes'],0,'Replication doubles DNA content, not the number of centromeres.'),q('What is the usual result here?',['Four haploid cells','Two diploid cells','One gamete'],1,'One division maintains the starting ploidy.')],investigation:['Pause at S/G2 and count chromosomes separately from chromatids.','Compare metaphase with anaphase. Track one colour to both poles.','Draw the two daughter cells and justify their chromosome number.'],teacher:'Assign pupils the roles of chromosomes and spindle fibres using cards. Ask the class to predict the next stage before advancing. Keep chromosome counts separate from DNA quantity.',misconception:'DNA copying is in interphase, not prophase. Mitosis can also occur in haploid cells; this example starts diploid.',source:'10-2-the-cell-cycle',limit:'A schematic 2n = 4 animal-cell example; stages have equal playback durations, not real biological durations.'},\n meiosis:{title:'Meiosis and genetic variation',intro:'Follow one DNA replication and two divisions. Compare homologous chromosome separation with sister chromatid separation.',principle:'Meiosis I reduces chromosome sets; meiosis II separates sister chromatids without another S phase.',steps:[\n {name:'Before S phase · 2n = 4',detail:'Two homologous pairs are shown: one long and one short. Blue and coral indicate the two parental origins, not sex chromosomes.'},\n {name:'DNA replication',detail:'Each of 4 chromosomes is copied into two sister chromatids. DNA replicates once before meiosis I.'},\n {name:'Prophase I · crossing over',detail:'Homologues pair. Non-sister chromatids exchange corresponding DNA segments; the marked tips show one illustrative crossover.'},\n {name:'Metaphase I',detail:'Homologous pairs align together. Their orientation is independent; use the orientation control to compare two possible arrangements.'},\n {name:'Anaphase I',detail:'Homologues separate, while sister chromatids remain joined. Each pole receives one member of each homologous pair.'},\n {name:'After meiosis I',detail:'Two haploid cells each contain n = 2 replicated chromosomes. Haploid does not mean that every chromosome has a single chromatid.'},\n {name:'Metaphase II',detail:'With no intervening DNA replication, replicated chromosomes align individually in each haploid cell.'},\n {name:'Anaphase II',detail:'Sister chromatids separate in both cells. The exchanged DNA segments can make sisters genetically different.'},\n {name:'Four haploid products',detail:'Each product has n = 2 single-chromatid chromosomes. Animal gametogenesis may produce unequal cytoplasm, as in oogenesis; four equal circles are a schematic.'}],\n questions:[q('What separates in meiosis I?',['Sister chromatids','Homologous chromosomes','Ribosomes'],1,'The reduction division separates homologues; sisters remain attached.'),q('Is there an S phase between meiosis I and II?',['Yes','No'],1,'One replication precedes the two divisions.'),q('Where does crossing over occur?',['Non-sister chromatids of homologues','Between unrelated cells','Only after fertilisation'],0,'Corresponding segments exchange between paired homologous chromosomes.')],investigation:['Compare 2n = 4 before S phase with n = 2 after division I.','Change orientation at metaphase I and track the short pair.','Toggle crossing over and compare the marked segments in all four products.'],teacher:'Give each pair two colours of long and short chromosome cards. Have students predict division-I products, then contrast the two types of separation with mitosis.',misconception:'Haploid chromosomes can still be replicated. Independent assortment and crossing over are distinct. Plant meiosis produces spores; gametes are not the universal direct product.',source:'11-1-the-process-of-meiosis',limit:'Two homologous pairs, one illustrative crossover and two selected orientations; not all genetic outcomes or actual cell geometry.'},\n transpiration:{title:'Transpiration in plants',intro:'Adjust humidity, air movement, temperature and stomatal opening. Compare a simplified relative water-loss index.',principle:'Evaporation and diffusion at leaves contribute to tension that draws water up xylem.',steps:[{name:'Root uptake',detail:'Water enters roots along a water-potential gradient. Roots do not act as a mechanical pump for the whole transpiration stream.'},{name:'Xylem transport',detail:'Cohesion and adhesion help maintain a continuous water column under tension. This model assumes an adequate water supply.'},{name:'Leaf evaporation',detail:'Water evaporates from moist mesophyll surfaces into leaf air spaces.'},{name:'Stomatal diffusion',detail:'Water vapour diffuses through stomata toward drier air. Guard cells regulate the aperture.'}],questions:[q('With everything else fixed, higher humidity usually…',['Lowers transpiration','Raises it indefinitely','Stops photosynthesis instantly'],0,'A smaller vapour gradient reduces diffusion.'),q('Which tissue carries this water stream?',['Phloem','Xylem','Epidermis only'],1,'Xylem transports water and dissolved mineral ions.'),q('Does this index predict field water loss in mL/hour?',['Yes','No'],1,'It is an illustrative relative index; leaf area and plant physiology are omitted.')],investigation:['Record the index at 20%, 50% and 80% humidity, keeping other controls fixed.','Repeat for air movement. Explain why it has diminishing influence here.','Close stomata and describe the trade-off between conserving water and taking in carbon dioxide.'],teacher:'Ask groups to predict an environmental effect before changing one variable. Keep a results table and compare fair tests. Discuss why drought-induced stomatal closure can reverse a simple temperature trend.',misconception:'Transpiration is water-vapour loss, not the upward water stream itself. A potometer estimates water uptake, which is not identical to water lost.',source:'30-5-transport-of-water-and-solutes-in-plants',limit:'Illustrative relative index, no physical rate units. Fixed water supply, no wilting, leaf-area variation, cuticular loss or automatic stomatal feedback.'},\n classification:{title:'Classification and scientific names',intro:'Search 90 organisms, compare their Domain and KPCOFGS ranks, and practise scientific names. Includes common animals, crops, fungi, protists, bacteria and an archaeon.',principle:'Nested taxa organise organisms; a scientific species name combines genus with specific epithet.',steps:[\n {name:'Domain',detail:'A level above kingdom. Compare Bacteria, Archaea and Eukarya. Domain here is mapped from the source kingdom, using the three-domain teaching framework.'},\n {name:'Kingdom',detail:'The source may use Animalia, Plantae, Fungi, Protozoa, Chromista, Bacteria or Archaea. These labels do not form the traditional five-kingdom scheme. Check the notes before comparing textbook answers.'},\n {name:'Phylum / Division',detail:'A broad grouping within a kingdom. Plant texts often use division in place of phylum. Compare organisms within the same source system.'},\n {name:'Class',detail:'A grouping within a phylum. Mammalia and Insecta are familiar examples. Reference systems may rank some groups differently, and not every record assigns this rank.'},\n {name:'Order',detail:'A grouping within a class when both ranks are assigned. Look for similarities and differences between two organisms, rather than judging from appearance alone.'},\n {name:'Family',detail:'A grouping above genus. For example, grasses include Poaceae and legumes include Fabaceae. Select maize/rice or cowpea/groundnut to compare.'},\n {name:'Genus',detail:'A genus groups related species. Capitalise and italicise the genus in a scientific name. Human and cat belong to different genera, Homo and Felis.'},\n {name:'Species',detail:'Use the full binomial: genus plus a lower-case specific epithet, both italicised. Common names can cover many species. Synonyms and subspecies need attention when matching a specimen to a reference.'}],questions:[q('Which rank is immediately above genus?',['Species','Family','Class'],1,'The sequence is order, family, genus, species.'),q('Which is correctly written?',['homo Sapiens','Homo sapiens','Sapiens'],1,'The genus starts with a capital and the epithet is lower case; italicise both.'),q('A missing rank in a reference should be…',['Invented from appearance','Marked as unassigned','Filled with the genus name'],1,'A reference can omit a rank. State the source instead of inventing a taxon.'),q('Monera and Protista are…',['Universal modern domains','Traditional teaching groupings','Two animal families'],1,'Modern sources split these older groupings differently. Always name the classification system.')],investigation:['Search and compare one Nigerian crop with another. Find their narrowest displayed shared rank.','Compare a vertebrate with an invertebrate, then a plant with a fungus. Explain which ranks differ.','Choose maize and rice, then cat and lion. Predict a selected rank before revealing it.','Compare Amoeba, Euglena and a bacterium. Explain why study groups are not necessarily kingdoms.','Find an unassigned rank or a synonym. Read the source note and explain how this changes marking a textbook answer.'],teacher:'Teams choose two organisms, hide the selected rank and invite predictions. Rotate the operator and explainer. Discuss any source differences rather than treating one ranked scheme as universal.',misconception:'A classification is not a ladder of progress. Broad common names are not species names. Identical rank labels across different systems need not describe identical evolutionary groups.',source:'20-1-organizing-life-on-earth',limit:'A saved GBIF Backbone reference collection with three-domain labels added. Ranks and accepted names can differ between sources; unassigned ranks are explicit. Study filters are not taxonomic ranks.'},\n 'life-processes':{title:'Characteristics of living things',intro:'Explore life processes and evaluate evidence. Mnemonics vary; use the named processes and the combined evidence rather than one sign alone.',principle:'Life is identified using interacting properties across cells, organisms and populations, not motion alone.',steps:[{name:'Movement',detail:'Animals may move from place to place; plants also show growth movements and internal transport. Motion alone does not establish life.'},{name:'Respiration',detail:'Cells release usable energy from chemical substrates. Cellular respiration is distinct from breathing and can be aerobic or anaerobic.'},{name:'Nutrition',detail:'Organisms obtain materials and energy. Photosynthesis is a mode of autotrophic nutrition; animals obtain organic nutrients by feeding.'},{name:'Sensitivity / irritability',detail:'Organisms detect and respond to stimuli, such as light, touch or chemical signals.'},{name:'Growth and development',detail:'Living systems grow through cellular processes and develop organised structures; simple external accumulation is not sufficient evidence of life.'},{name:'Excretion',detail:'Removal of metabolic wastes such as carbon dioxide or nitrogenous compounds. Egestion of undigested food is different.'},{name:'Reproduction',detail:'New organisms arise from living systems. A sterile individual can still be alive; reproduction describes continuation of lineages.'},{name:'Death',detail:'Individual life ends through irreversible loss of integrated function. Death alone is not a diagnostic test for life.'},{name:'Competition',detail:'Organisms may compete for limited resources. Competition also occurs in other systems, so it is not sufficient evidence on its own.'},{name:'Adaptation',detail:'Heritable traits can become more common across generations through natural selection. This differs from short-term acclimatisation of an individual.'}],questions:[q('A car moves and uses fuel. Is that alone evidence it is alive?',['Yes','No'],1,'Life requires a coordinated set of properties including cellular organisation.'),q('Excretion is…',['Removal of metabolic waste','Removal of undigested food','Only movement'],0,'Egestion concerns undigested food; excretion concerns metabolic wastes.'),q('A sterile animal is…',['Not alive','Still alive'],1,'An individual need not reproduce to be alive.')],investigation:['For each process, propose a plant example and an animal example.','Compare a seed, a flame and a moving vehicle using several lines of evidence.','Explain respiration versus breathing and adaptation versus acclimatisation.'],teacher:'Ask groups to sort evidence cards into strong, weak and insufficient evidence for life. Include a dormant seed so lack of visible movement is not treated as proof of non-life.',misconception:'MRNIGERDCA is a memory aid, not a universal definition. Homeostasis, cellular organisation and evolution also matter; the processes should be considered together.',source:'1-2-themes-and-concepts-of-biology',limit:'A conceptual explorer, not a biological test or a claim that every process must be visibly present in every individual.'}\n};\nexport function transpirationIndex(humidity:number,wind:number,temperature:number,opening:number){\n const clamp=(x:number,lo:number,hi:number)=>Math.min(hi,Math.max(lo,x));\n return 100*(1-clamp(humidity,0,100)/100)*(0.5+0.5*clamp(wind,0,5)/(1+clamp(wind,0,5)))*Math.pow(1.04,clamp(temperature,10,40)-25)*clamp(opening,0,100)/100;\n}\n"}, "checks/biology-images.cjs": {"encoding": "utf8", "content": "const fs=require('fs'),path=require('path'),vm=require('vm'),ts=require('typescript'),assert=require('assert'),React=require('react'),{renderToStaticMarkup}=require('react-dom/server');\nconst slots=[],cache=new Map();let cursor=0;\nconst stub=()=>null,hooks={...React,useState(v){const i=cursor++;if(!(i in slots))slots[i]=typeof v==='function'?v():v;return[slots[i],v=>slots[i]=typeof v==='function'?v(slots[i]):v];},useEffect:()=>{}};\nfunction load(file){file=path.resolve(file);if(cache.has(file))return cache.get(file).exports;const module={exports:{}};cache.set(file,module);function req(id){if(id==='react')return hooks;if(id==='react/jsx-runtime')return require(id);if(id==='next/link')return {__esModule:true,default:stub};if(id.includes('/use-topic-preset'))return{useTopicPreset:()=>{}};for(const name of ['AppHeader','SimulationStage','ReadAloud','EmbedButton'])if(id.endsWith('/'+name))return{[name]:stub};if(id.endsWith('.css'))return{};let target=id.startsWith('@/')?'src/'+id.slice(2):id.startsWith('.')?path.resolve(path.dirname(file),id):null;if(!target)return require(id);if(target.endsWith('.json'))return JSON.parse(fs.readFileSync(target,'utf8'));if(!path.extname(target))target+=fs.existsSync(target+'.ts')?'.ts':'.tsx';return load(target);}\nconst code=ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText;vm.runInNewContext(code,{module,exports:module.exports,require:req,console,Math,URLSearchParams});return module.exports;}\nconst media=JSON.parse(fs.readFileSync('src/lib/biology/reference-images.json','utf8')),organisms=JSON.parse(fs.readFileSync('src/lib/biology/organisms.json','utf8'));\nassert.equal(Object.keys(media.cells).length,4);assert.equal(Object.keys(media.organisms).length,90);let included=0;\nfor(const o of organisms){assert(o.id in media.organisms);const m=media.organisms[o.id];if(!m)continue;if(m.src.startsWith('/')){included++;assert(m.src.startsWith('/biology/reference/'));assert(fs.statSync('public'+m.src).size>100);}else{assert(m.src.startsWith('https://'));assert(m.source.includes('commons.wikimedia.org/wiki/File:'));}assert(m.width>0&&m.height>0);assert(m.width>0&&m.height>0);assert(m.source.startsWith('https://www.inaturalist.org/photos/')||m.source.includes('commons.wikimedia.org/wiki/File:'));assert(m.license==='CC0'||m.license==='Public domain'||/^CC[- ]BY/.test(m.license));assert(m.artist.length>0);}\nassert(included>=50,'broad reference photograph coverage');for(const m of Object.values(media.cells)){assert(m.src.startsWith('https://'));assert(m.source.includes('commons.wikimedia.org/wiki/File:'));assert(m.artist.length>0&&m.license.length>0);}\nconst {CellReference}=load('src/components/biology/CellReference.tsx'),{ClassificationModel}=load('src/components/biology/ClassificationModel.tsx');\nconst errors=[],original=console.error;console.error=(...a)=>errors.push(a.join(' '));try{for(const plant of [false,true])for(const view of ['illustration','microscope'])for(const labels of [true,false]){const h=renderToStaticMarkup(CellReference({plant,view,selected:0,labels,interactive:true,onSelect:()=>{}}));assert(h.includes('<img'));assert(h.includes(view==='microscope'?'actual microscope image':'scientific illustration'));assert(h.includes('Image credit and source'));assert(h.includes('Open the credited source'));}\nfor(let primary=0;primary<90;primary++){const h=renderToStaticMarkup(ClassificationModel({primary,comparison:(primary+1)%90}));assert(h.includes('Organism rank comparison'));assert(h.includes('<img')||h.includes('No verified image'));}}finally{console.error=original;}assert.deepEqual(errors,[]);\nconst {prepare}=load('src/lib/explorer/prepare.ts');assert.equal(prepare({prompt:'cells cellView=microscope',language:'en'}).modes.cellView,'microscope');\nfunction nodes(tree){let all=[];function walk(n){if(!React.isValidElement(n))return;all.push(n);React.Children.forEach(n.props.children,walk);}walk(tree);return all;}\nconst text=n=>typeof n==='string'||typeof n==='number'?String(n):React.isValidElement(n)?React.Children.toArray(n.props.children).map(text).join(''):'';\nconst {BiologyLesson}=load('src/components/biology/BiologyLesson.tsx');function render(){cursor=0;return nodes(BiologyLesson({topic:'cells'}));}let n=render();let label=n.find(x=>x.type==='label'&&text(x).startsWith('Image view'));nodes(label).find(x=>x.type==='select').props.onChange({target:{value:'microscope'}});n=render();assert(n.some(x=>x.props.topic==='cells'&&x.props.cellView==='microscope'));assert(n.some(x=>x.props.params?.cellView==='microscope'));n.find(x=>x.type==='button'&&text(x)==='Reset lesson').props.onClick();n=render();assert(n.some(x=>x.props.topic==='cells'&&x.props.cellView==='illustration'));\nconsole.log(`PASS: ${included} bundled licensed organism images, four credited cell references, image/error rendering without React warnings, microscopy view handoff, embed state and reset.`);\n"}, "public/biology/reference/escherichia-coli.jpeg": {"encoding": "base64", "content": ""}, "public/biology/reference/pandinus-imperator.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/agaricus-bisporus.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/felis-catus.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/oryza-sativa.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/rhizopus-stolonifer.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/danaus-plexippus.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/cocos-nucifera.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/triticum-aestivum.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/aspergillus-niger.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/halobacterium-salinarum.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/saccharum-officinarum.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/arachis-hypogaea.jpeg": {"encoding": "base64", "content": ""}, "public/biology/reference/ovis-aries.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/rana-temporaria.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/solanum-tuberosum.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/struthio-camelus.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/lumbricus-terrestris.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/taenia-solium.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/oryctolagus-cuniculus.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/carica-papaya.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/elaeis-guineensis.jpeg": {"encoding": "base64", "content": ""}, "public/biology/reference/panthera-leo.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/dryopteris-filix-mas.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/helianthus-annuus.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/columba-livia.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/abelmoschus-esculentus.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/pinus-sylvestris.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/mangifera-indica.jpg": {"encoding": "base64", "content": ""}, "public/biology/reference/mus-musculus.jpg": {"encoding": "base64", "content