const root=process.cwd();
function stop(message){console.error('Stopped: '+message+' No application files changed.');process.exit(1);}
if(!fs.existsSync('package.json')||!fs.existsSync('src/components/biology/ClassificationModel.tsx'))stop('Run from the A-Factor project root after patch-classification-90-organisms.sh.');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const data=(file)=>Buffer.from(files[file].content,files[file].encoding);
const normal=b=>b.toString('utf8').replace(/\r\n/g,'\n');
function safe(file){let current=root;for(const part of file.split('/')){current=path.join(current,part);try{if(fs.lstatSync(current).isSymbolicLink())stop('Symbolic link at '+file);}catch(e){if(e.code!=='ENOENT')throw e;}}}
for(const file of [...Object.keys(files),'.stem-tutor-backups'])safe(file);
const changed=[],conflicts=[];
for(const file of Object.keys(files)){
 const old=fs.existsSync(file)?fs.readFileSync(file):null,content=data(file),text=files[file].encoding==='utf8';
 if(old!==null&&(text?normal(old)===normal(content):old.equals(content)))continue;
 if((old===null&&expected[file]!==null)||(old!==null&&(expected[file]===null||hash(text?normal(old):old)!==expected[file])))conflicts.push(file);else changed.push(file);
}
if(conflicts.length)stop('These files differ from the state after patch-classification-90-organisms.sh. Keep your edits and request a refreshed patch:\n'+conflicts.join('\n'));
if(!changed.length){console.log('Biology reference imagery is already installed.');process.exit(0);}
fs.mkdirSync('.stem-tutor-backups',{recursive:true});const backup=fs.mkdtempSync('.stem-tutor-backups/biology-images-'),originals=new Map();
for(const file of changed){const old=fs.existsSync(file)?fs.readFileSync(file):null;originals.set(file,old);if(old!==null){const copy=path.join(backup,file);fs.mkdirSync(path.dirname(copy),{recursive:true});fs.writeFileSync(copy,old);}}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify(changed.map(file=>({file,existed:originals.get(file)!==null})),null,2));
try{for(const file of changed){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,data(file));}}catch(error){for(const [file,old]of originals){if(old===null){if(fs.existsSync(file))fs.unlinkSync(file);}else fs.writeFileSync(file,old);}console.error('Write failed; originals restored: '+error.message);process.exit(1);}
console.log('Installed '+changed.length+' files: Biology reference photographs, cell illustrations and micrographs with credits.');
console.log('Backup: '+backup);
console.log('77 organism images are bundled. 13 organism references and four cell images are Wikimedia-hosted and require internet; credited source links remain available.');
